#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include "packet_parser.h"

/*
 * ============================================================================
 * Standalone Crash Reproducer
 * ============================================================================
 * Reads a crash artifact generated by the fuzzer from disk and executes it
 * through parse_packet() under AddressSanitizer or GDB for root-cause analysis.
 */

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <crash_file_or_payload>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        perror("fopen");
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    if (size <= 0) {
        fprintf(stderr, "[-] File is empty.\n");
        fclose(f);
        return 1;
    }

    uint8_t *buffer = (uint8_t *)malloc(size);
    if (!buffer) {
        fclose(f);
        return 1;
    }

    size_t read_bytes = fread(buffer, 1, size, f);
    fclose(f);

    printf("[*] Loaded %zu bytes from '%s'. Parsing...\n", read_bytes, argv[1]);
    int result = parse_packet(buffer, read_bytes);
    printf("[*] parse_packet() returned: %d\n", result);

    free(buffer);
    return 0;
}
